CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', avatar_path text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_owner ON public.profiles FOR ALL TO authenticated USING (id = (SELECT auth.uid())) WITH CHECK (id = (SELECT auth.uid()));
CREATE TABLE public.inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid, full_name text NOT NULL, email text NOT NULL, phone text NOT NULL, category text NOT NULL, subject text NOT NULL, message text NOT NULL, kind text NOT NULL, acknowledgment boolean NOT NULL DEFAULT true CHECK (acknowledgment = true), created_at timestamptz NOT NULL DEFAULT now());
GRANT INSERT ON public.inquiries TO anon, authenticated;
GRANT SELECT ON public.inquiries TO authenticated;
GRANT ALL ON public.inquiries TO service_role;
ALTER TABLE public.inquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY inquiries_insert ON public.inquiries FOR INSERT TO anon, authenticated WITH CHECK ((user_id IS NULL OR user_id = (SELECT auth.uid())) AND length(full_name) BETWEEN 2 AND 120 AND length(email) BETWEEN 3 AND 254 AND length(phone) BETWEEN 7 AND 40 AND length(subject) BETWEEN 3 AND 200 AND length(message) BETWEEN 20 AND 5000 AND category IN ('Corporate Legal Matters','Business Disputes','Contract Disputes','Litigation','Intellectual Property','Tax and Regulatory Issues','Mergers and Acquisitions','Other Legal Matters') AND kind IN ('consultation','assessment','general','attorney'));
CREATE POLICY inquiries_owner_read ON public.inquiries FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE INDEX inquiries_user ON public.inquiries(user_id);
CREATE TABLE public.matters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, title text NOT NULL, category text NOT NULL, status text NOT NULL DEFAULT 'Awaiting review', representative text NOT NULL DEFAULT 'Not yet assigned', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.matters TO authenticated;
GRANT ALL ON public.matters TO service_role;
ALTER TABLE public.matters ENABLE ROW LEVEL SECURITY;
CREATE POLICY matters_owner_read ON public.matters FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE INDEX matters_user ON public.matters(user_id);
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, message text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.notifications TO authenticated;
GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY notifications_owner_read ON public.notifications FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE INDEX notifications_user ON public.notifications(user_id);
CREATE TABLE public.demo_payments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, reference text NOT NULL CHECK (length(reference) BETWEEN 3 AND 100), description text NOT NULL CHECK (description IN ('Consultation Fee','Legal Services','Invoice Payment','Retainer','Outstanding Balance')), amount_cents integer NOT NULL CHECK (amount_cents > 0 AND amount_cents <= 100000000), simulated boolean NOT NULL DEFAULT true CHECK (simulated = true), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.demo_payments TO authenticated;
GRANT ALL ON public.demo_payments TO service_role;
ALTER TABLE public.demo_payments ENABLE ROW LEVEL SECURITY;
CREATE POLICY payments_owner_read ON public.demo_payments FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()));
CREATE POLICY payments_owner_insert ON public.demo_payments FOR INSERT TO authenticated WITH CHECK (user_id = (SELECT auth.uid()) AND simulated = true);
CREATE INDEX payments_user ON public.demo_payments(user_id);
CREATE POLICY documents_owner_read ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'client-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);
CREATE POLICY documents_owner_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'client-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);
CREATE POLICY documents_owner_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'client-documents' AND (storage.foldername(name))[1] = (SELECT auth.uid())::text);